import fs from "fs";
const f = "khmer.extra28.mjs", norm = (s) => s.trim().toLowerCase();
const live = process.env.HOME + "/ai-project/AI/src/ai/khmer.mjs";
const srcs = [...fs.readdirSync(".").filter((x) => /^khmer\.extra\d+[a-z]?\.mjs$/.test(x) && x !== f), live]
  .filter((x) => fs.existsSync(x)).map((x) => fs.readFileSync(x, "utf8"));
const seen = new Set();
for (const t of srcs) for (const m of t.matchAll(/\[\s*"([^"\n]+)"\s*,/g)) m[1].split("|").forEach((a) => seen.add(norm(a)));
const has = (a) => seen.has(a) || srcs.some((t) => t.includes('"' + a + '"'));
const out = [], drop = [], own = new Set();
for (const line of fs.readFileSync(f, "utf8").split("\n")) {
  const m = line.match(/^\s*\["([^"]+)"/);
  if (!m) { out.push(line); continue; }
  const al = m[1].split("|").map(norm);
  if (al.some((a) => has(a) || own.has(a))) { drop.push(m[1]); continue; }
  al.forEach((a) => own.add(a)); out.push(line);
}
fs.writeFileSync(f, out.join("\n"));
console.log("ជាន់ (ដកចេញ):", drop.length, drop.join(" "));
const m = await import("./" + f);
console.log("entries សល់:", m.EXTRA_ENTRIES_28.length);
EOF
